mapper.select:
select r.id AS id, r.task_id AS taskId, r.request_number AS requestNumber, r.request_org AS requestOrg, r.request_time AS requestTime, r.request_title AS requestTitle, r.request_content AS requestContent, r.is_valid AS isValid, r.is_audit AS isAudit, s.name AS creatorName, r.create_time AS createTime, u.name AS editorName, r.edit_time AS editTime, e.name AS currentName, e.name AS auditorName, r.audit_time AS auditTime, t.task_name AS taskName from request_info r left join sys_user s on r.creator_id=s.id left join sys_user u on r.editor_id=u.id left join sys_user e on r.auditor_id=e.id left join task_info t on r.task_id=t.id
AND r.request_title like CONCAT('%',#{requestTitle}, '%')
AND r.request_content like CONCAT('%',#{requestContent},'%')
AND r.request_number like CONCAT('%',#{requestNumber},'%')
AND r.is_audit=${isAudit}
AND r.is_valid=${isValid}
AND r.IS_VALID != -1
AND r.request_time >= #{beginDate}
AND r.request_time <= #{endDate}
AND r.edit_time >= #{dobeginDate}
AND r.edit_time <= #{doendDate}
${sqlMap.dsf}
ORDER BY ${page.orderBy}
ORDER BY r.create_time desc
